    [Test]
    public async Task BoolSuppressedWithItsNativeSignatureShouldReportNothing()
    {
        const string source = """
            using System.Diagnostics.CodeAnalysis;
            using System.Runtime.InteropServices;

            namespace KappaDuck.Khaos.Interop.Win32;

            internal static partial class Kernel32
            {
                [LibraryImport("kernel32", EntryPoint = "TryAcquireSRWLockExclusive")]
                [return: MarshalAs(UnmanagedType.U1)]
                [SuppressMessage("Interop", "KHI001", Justification = "TryAcquireSRWLockExclusive returns BOOLEAN (1 byte), not BOOL.")]
                internal static partial bool TryAcquireSRWLockExclusive(nuint lockHandle);
            }
            """;

        AnalyzerResult result = await AnalyzerRunner<InteropBoolMarshallingAnalyzer>.RunAsync(source);

        await result.CompilationErrors.Should().BeEmpty();
        await result.Located.Should().BeEmpty();
    }
